        { id: 'sponsor', color: '#00d400' },
        { id: 'selfpromo', color: '#ffff00' },
        { id: 'interaction', color: '#cc00ff' },
        { id: 'intro', color: '#00ffff' },
        { id: 'outro', color: '#0202ed' },
        { id: 'preview', color: '#008fd6' },
